//! Diagnostic only: low-speed Newtonian RK4; neither canonical outcomes nor a gate.
use emergent_universe::{Config,fleet::Order,scenario::plane,thrust::{word,direction,alpha_log2},view::TICK_SECONDS,num::to_f64,observe::held_thrust};
fn derivative(y:[f64;4],mu:f64,a:[f64;2])->[f64;4]{let r=y[0].hypot(y[1]);[y[2],y[3],-mu*y[0]/r.powi(3)+a[0],-mu*y[1]/r.powi(3)+a[1]]}
fn main(){let args:Vec<String>=std::env::args().collect();let q:i32=args[1].parse().unwrap();let d=Config::default();let cfg=Config{step_log2:d.step_log2+q,thrust_quantum_log2:d.thrust_quantum_log2+q,..d};let mut p=plane(cfg,5,Order::Sparse,1,8).unwrap();let start=2_000_000;p.u.settle(start);let rec=p.u.rec(p.player);let doll=&p.u.dolls[rec.b.doll as usize];let length=299792458.0*TICK_SECONDS/2f64.powi(doll.shift as i32);let mu=to_f64(doll.unit.mu)*length*299792458.0f64.powi(2);let (x,v)=rec.b.cartesian(start).unwrap();let n=direction(rec.thrust.unwrap().heading).unwrap().map(to_f64);let acceleration=2f64.powi(alpha_log2(&d,4) as i32)*299792458.0/TICK_SECONDS;let a=n.map(|n|n*acceleration);let mut y=[to_f64(x[0])*length,to_f64(x[1])*length,to_f64(v[0])*299792458.0,to_f64(v[1])*299792458.0];p.u.input(start,word(1,4)).unwrap();println!("q{q} initial={y:?} mu={mu} a={a:?}");
 for j in 1..=8000 {let h=0.25;let k1=derivative(y,mu,a);let k2=derivative(std::array::from_fn(|i|y[i]+h*k1[i]/2.0),mu,a);let k3=derivative(std::array::from_fn(|i|y[i]+h*k2[i]/2.0),mu,a);let k4=derivative(std::array::from_fn(|i|y[i]+h*k3[i]),mu,a);y=std::array::from_fn(|i|y[i]+h*(k1[i]+2.0*k2[i]+2.0*k3[i]+k4[i])/6.0);
  if [40,80,200,400,800,2000,4000,8000].contains(&j){let t=start+((j as f64*h)/TICK_SECONDS) as i64;p.u.settle(t);let r=p.u.rec(p.player);let (x,v)=r.b.cartesian(t).unwrap();let (_,dv)=held_thrust(&p.u.ctx(),&r,t).unwrap().unwrap();let actual=[to_f64(x[0])*length,to_f64(x[1])*length,(to_f64(v[0])+dv[0])*299792458.0,(to_f64(v[1])+dv[1])*299792458.0];let err:[f64;4]=std::array::from_fn(|i|actual[i]-y[i]);println!("q{q} seconds={} interval_s={} error_m_mps={err:?}",j as f64*h,r.interval as f64*TICK_SECONDS);}
 }
}
